#!/bin/sh
# SCHEM-NL-09 capture driver, generated by tools/golden/authoring/schem_cases.py (m8-schematic design D16).
# Each run is a fresh xschem netlist run; the driver prints its exit status and exits with
# the last non-zero one.
status=0
mkdir -p out
run() {
  label=$1; shift
  echo "== $label"; echo "== $label" >&2
  "$@"; rc=$?
  echo "== $label: exit $rc"
  if [ "$rc" -ne 0 ]; then status=$rc; fi
}
run test_nfet_03v3 xschem -q -x -r --rcfile /work/input/xschemrc -n -s -o /work/out /pdk/gf180mcuD/libs.tech/xschem/tests/test_nfet_03v3.sch
run test_cap_mim_1f0fF xschem -q -x -r --rcfile /work/input/xschemrc -n -s -o /work/out /pdk/gf180mcuD/libs.tech/xschem/tests/test_cap_mim_1f0fF.sch
exit "$status"
